(function(){"use strict";function initBlogStickyWidgets(){var isBlogListing=document.body.classList.contains("blog-page");var isBlogDetail=document.body.classList.contains("blog-details-page");if(!isBlogListing&&!isBlogDetail)return;var header=document.querySelector("#sticky-header, .tg-header__area, .header__area, header");var pageConfig=isBlogDetail?{layout:document.querySelector(".blog-details-layout"),boundary:document.querySelector(".blog__details-area")||document.querySelector(".blog-details-layout"),widgets:[{slot:document.querySelector(".blog-details-left-recent-sticky-slot"),inner:document.querySelector(".blog-details-left-recent-sticky-inner"),minWidth:1651},{slot:document.querySelector(".blog-details-right-sticky-slot"),inner:document.querySelector(".blog-details-right-sticky-inner"),minWidth:992}]}:{layout:document.querySelector(".blog-listing-layout"),boundary:document.querySelector(".blog__post-area-five")||document.querySelector(".blog-listing-layout"),widgets:[{slot:document.querySelector(".blog-left-recent-sticky-slot"),inner:document.querySelector(".blog-left-recent-sticky-inner"),minWidth:1651},{slot:document.querySelector(".blog-right-sticky-slot"),inner:document.querySelector(".blog-right-sticky-inner"),minWidth:992}]};var layout=pageConfig.layout;var boundaryElement=pageConfig.boundary||layout;var bottomGap=40;var widgets=pageConfig.widgets.filter(function(item){return item.slot&&item.inner});if(!layout||!widgets.length)return;var ticking=false;function getOffset(){var headerHeight=header?header.getBoundingClientRect().height:90;return headerHeight+24}function resetWidget(item){item.inner.style.position="";item.inner.style.top="";item.inner.style.left="";item.inner.style.right="";item.inner.style.width="";item.inner.style.maxWidth="";item.inner.style.maxHeight="";item.inner.style.minHeight="";item.inner.style.height="";item.inner.style.overflow="";item.inner.style.zIndex="";item.inner.style.boxSizing="";item.inner.style.transform="";item.slot.style.minHeight="";item.slot.style.position="";item.slot.style.overflow="";item.slot.style.boxSizing=""}function isInRange(item){var width=window.innerWidth;if(item.minWidth&&width<item.minWidth)return false;if(item.maxWidth&&width>item.maxWidth)return false;return true}function getNextBoundaryTop(scrollY){var boundaryCandidates=[".footer-main-cta",".cta__area-two","footer",".footer__area"];var boundaryRect=boundaryElement.getBoundingClientRect();var boundaryBottom=boundaryRect.top+scrollY+boundaryElement.offsetHeight;for(var i=0;i<boundaryCandidates.length;i+=1){var candidate=document.querySelector(boundaryCandidates[i]);if(!candidate)continue;var candidateTop=candidate.getBoundingClientRect().top+scrollY;if(candidateTop>boundaryRect.top+scrollY&&candidateTop<boundaryBottom+400){return candidateTop}}return boundaryBottom}function getBoundaryRect(scrollY){var boundary=boundaryElement||layout;var rect=boundary.getBoundingClientRect();var sectionBottom=rect.top+scrollY+boundary.offsetHeight;var stopBottom=Math.min(sectionBottom,getNextBoundaryTop(scrollY));return{top:rect.top+scrollY,bottom:stopBottom}}function updateWidget(item){resetWidget(item);if(!isInRange(item))return;var slotRect=item.slot.getBoundingClientRect();if(!slotRect.width)return;var scrollY=window.pageYOffset||document.documentElement.scrollTop;var offset=getOffset();var slotTop=slotRect.top+scrollY;var innerHeight=item.inner.offsetHeight;var boundary=getBoundaryRect(scrollY);var stopPoint=boundary.bottom-bottomGap-innerHeight-offset;item.slot.style.position="relative";item.slot.style.minHeight=innerHeight+"px";item.slot.style.boxSizing="border-box";if(scrollY+offset<slotTop)return;if(scrollY>=stopPoint){item.inner.style.position="absolute";item.inner.style.top=Math.max(0,boundary.bottom-bottomGap-slotTop-innerHeight)+"px";item.inner.style.left="0";item.inner.style.width=slotRect.width+"px";item.inner.style.maxWidth=slotRect.width+"px";item.inner.style.zIndex="3";item.inner.style.boxSizing="border-box";return}item.inner.style.position="fixed";item.inner.style.top=offset+"px";item.inner.style.left=slotRect.left+"px";item.inner.style.width=slotRect.width+"px";item.inner.style.maxWidth=slotRect.width+"px";item.inner.style.zIndex="3";item.inner.style.boxSizing="border-box"}function updateAll(){ticking=false;widgets.forEach(updateWidget)}function requestUpdate(){if(ticking)return;ticking=true;window.requestAnimationFrame(updateAll)}window.addEventListener("scroll",requestUpdate,{passive:true});window.addEventListener("resize",requestUpdate);window.addEventListener("load",requestUpdate);requestUpdate();window.setTimeout(requestUpdate,300);window.setTimeout(requestUpdate,1e3)}if(document.readyState==="loading"){document.addEventListener("DOMContentLoaded",initBlogStickyWidgets)}else{initBlogStickyWidgets()}})();